class Godly {
	constructor() {

	}
	static init() {
			for (var cls in Godly.SETS) {
				var st = Godly.SETS[cls];
				Data.SETS["g_" + cls] = {name: st.name, bonus: st.bonus};
			}
			for (var b in Godly.DROPS) {
				var def = Data.ENEMIES[b];
				if (!def) continue;
				def.godly = Godly.DROPS[b];
				for (var d of __vals( Godly.DROPS[b])) Godly.source[d[0] + d[1]] = def.name;
			}
		}
	static make(cls, slot) { slot = __int(slot);
			var st = Godly.SETS[cls];
			var c = Data.CLASSES[cls];
			var it = slot == 0 ? Data.makeWeapon(c.weapon, 7, "gd", "") : Data.makeForSlot(c, slot, 7, "gd");
			it.name = st.items[slot];
			it.set = "g_" + cls;
			it.gid = cls + slot;
			if (slot == 0) {
				var x = st.weapon;
				if (x.shots) { it.shots = x.shots; it.parallel = x.parallel == true; }
				if (x.arc != undefined) it.arc = x.arc;
				if (x.rate) it.rate = x.rate;
				if (x.motion) it.motion = x.motion;
				if (x.pierce) it.pierce = true;
				if (x.size) it.size = x.size;
				if (x.col) it.col = x.col;
				if (x.passive) it.passive = x.passive;
				var mult = x.mult || (x.shots ? Math.max(0.6, 1.6 / Math.sqrt(x.shots)) : 1);
				it.dmin = __int(it.dmin * mult);
				it.dmax = __int(it.dmax * mult);
				delete it.form;
			}
			return it;
		}
	static roll(def, items, boost) {
			if (!def.godly) return;
			
			if (def.godly.length && Math.random() < Godly.CHANCE * boost) {
				var d = def.godly[__int(Math.random() * def.godly.length)];
				items.push(Godly.make(d[0], d[1]));
			}
		}
	static describe(it) {
			var src = Godly.source[it.gid];
			return "<font color='#fff6e0'>Godly: 1 in 1,000" + (src ? " from " + src : "") + ".</font>\n";
		}
}

